pub const KEYS: &[CcKey] = &[
    CcKey { key: "advisorModel", tab: 1, kind: Text, scope: "Any file", tui: false, help: "Pick which model answers when Claude calls the server-side advisor tool. Unset it to turn the advisor off. The advisor must be at least as capable as your main model. See Choose an advisor model for the accepted pairings and what happens when you pick one that isn't accepted. Default: unset, so the advisor is off." },
    CcKey { key: "alwaysThinkingEnabled", tab: 1, kind: Bool, scope: "Any file", tui: false, help: "Turn extended thinking off for every session by setting this to false. Thinking is on by default, so true changes nothing. Most people set this through /config rather than by editing the file. Default: unset, so thinking is on for models that support it." },
    CcKey { key: "availableModels", tab: 1, kind: Json, scope: "Any file", tui: false, help: "Restrict which models people can select for the main session, subagents, skills, and the advisor. A managed list constrains /model, --model, and the model key in a developer's own files; a model outside it can't be selected. With the default prefix matching, this doesn't touch the Default option on its own; pair it with enforceAvailableModels for that. Default: unset, so every model is available." },
    CcKey { key: "effortLevel", tab: 1, kind: Choice(&["low", "medium", "high", "xhigh"]), scope: "Any file", tui: false, help: "Set a default effort level for models you haven't saved a level for. Lower levels are faster and cheaper on straightforward tasks, and higher levels reason more deeply on complex problems. Default: unset." },
    CcKey { key: "enforceAvailableModels", tab: 1, kind: Bool, scope: "Any file", tui: false, help: "The /model picker has a Default option, and default model setting describes the model it resolves to. An availableModels allowlist limits the models you can name, but with the default prefix matching it doesn't remap your account type's default, so Default can still resolve to a model outside the list. This key closes that gap. Requires Claude Code v2.1.175 or later. Default: false." },
    CcKey { key: "fallbackModel", tab: 1, kind: Json, scope: "Any file", tui: false, help: "Name backup models for Claude Code to try, in order, when your primary model is overloaded or unavailable. Claude Code switches to the next available model in the chain for the rest of the turn and shows a notice. Without a chain, Claude Code retries the same model and then surfaces the server's error, and you retry or switch models yourself. Default: unset, so a failed request isn't retried on another model." },
    CcKey { key: "fastMode", tab: 1, kind: Bool, scope: "Any file", tui: false, help: "Turn fast mode on for sessions where it's available, for interactive work like rapid iteration or live debugging where you want speed at a higher cost per token. You don't usually edit this key by hand: running /fast writes fastMode: true to ~/.claude/settings.json, and running it again to turn fast mode off removes the key. Fast mode runs only on Opus 5.5, Opus 5, and Opus 4.8: turning it on from another model switches you to Opus, and switching to an unsupported model turns it off. See Switch models while fast mode is on. Default: unset, so fast mode is off." },
    CcKey { key: "fastModePerSessionOptIn", tab: 1, kind: Bool, scope: "Any file", tui: false, help: "Normally, running /fast saves fastMode to a person's user settings, so fast mode is on at the start of every later session. Set this key to true to stop that: a saved fastMode: true no longer turns fast mode on at session start, and each person has to run /fast in each session they want it. Claude Code leaves the fastMode key in their file, so turning this key off restores the old behavior. Default: false." },
    CcKey { key: "language", tab: 1, kind: Text, scope: "Any file", tui: false, help: "Have Claude respond in a language other than English by default. There is no fixed list for responses: Claude Code passes the value verbatim to Claude as an instruction to always respond in that language, so any language name Claude can read works. Claude Code doesn't check the value, so a misspelled name reaches Claude as written rather than producing an error. The same value sets the language for voice dictation, which does have a fixed list of supported dictation languages, and for auto-generated session titles. Default: unset; session titles then match the language of your conversation." },
    CcKey { key: "maxEffortLevel", tab: 1, kind: Choice(&["low", "medium", "high", "xhigh", "max"]), scope: "Any file", tui: false, help: "Cap the effort level a session can use, leaving lower levels available. Any higher level runs at the cap instead, including one from /effort, the /model picker, --effort, CLAUDE_CODE_EFFORT_LEVEL, a skill's or subagent's effort frontmatter, or the model's own default. Claude Code applies the cap itself before each request, so it holds on every provider, including Amazon Bedrock, Google Cloud's Agent Platform, and Microsoft Foundry. Requires Claude Code v2.1.267 or later. Default: unset, so no cap applies." },
    CcKey { key: "model", tab: 1, kind: Text, scope: "Any file", tui: false, help: "Set the model every new session uses, so you don't have to pick one with /model each time. Setting it here doesn't stop you from switching mid-session. If your admin set an organization default model to override user selection, you get that model even when you set this key in user, project, or local settings. Default: unset, so Claude Code uses your account's default model." },
    CcKey { key: "modelOverrides", tab: 1, kind: Json, scope: "Any file", tui: false, help: "Map Anthropic model IDs to provider-specific model IDs, such as Amazon Bedrock inference profile ARNs. Each model picker entry then uses its mapped value when calling the provider API. Administrators use this on Amazon Bedrock, Google Cloud's Agent Platform, and Microsoft Foundry to route each model version to a specific inference profile, version name, or deployment for governance, cost allocation, or regional routing. Default: unset." },
    CcKey { key: "modelPicker", tab: 1, kind: Json, scope: "User or managed", tui: false, help: "List the models the /model picker offers, in the order you write them and under labels you choose, so the picker lists the models your organization runs, after the built-in lineup or instead of it. Each row's model is taken verbatim, so it accepts anything --model accepts: an alias such as opus, an Anthropic model ID, or a provider-format ID for Amazon Bedrock, Google Cloud's Agent Platform, Microsoft Foundry, or an LLM gateway. Requires Claude Code v2.1.242 or later. Default: unset, so the picker shows the built-in lineup." },
    CcKey { key: "modelSettings", tab: 1, kind: Json, scope: "Any file", tui: false, help: "Save an effort level for each model you use. Requires Claude Code v2.1.251 or later. Default: unset." },
    CcKey { key: "outputStyle", tab: 1, kind: Text, scope: "Any file", tui: false, help: "Select an output style by name. An output style is a saved set of instructions that changes Claude's role, tone, and output format, such as the built-in Explanatory and Learning styles or one you wrote yourself. Default: unset, so Claude Code uses the default style." },
    CcKey { key: "promptCacheTtl", tab: 1, kind: Choice(&["5m", "1h"]), scope: "Any file", tui: false, help: "Choose how long the prompt cache holds the main conversation. This key applies to your interactive, -p, and Agent SDK turns, together with the helpers Claude Code runs inline with them. The one-hour lifetime keeps the cache warm across longer breaks, and the API bills each cache write at a higher rate than at the five-minute lifetime. Requires Claude Code v2.1.242 or later. Default: unset, so each main-conversation request gets its default lifetime." },
    CcKey { key: "showThinkingSummaries", tab: 1, kind: Bool, scope: "Any file", tui: false, help: "See summaries of Claude's extended thinking in interactive sessions. Set it if you want the full summaries when you expand thinking with Ctrl+O. When unset or false, the Anthropic API redacts thinking blocks and Claude Code shows a collapsed stub. Default: false." },
    CcKey { key: "subagentPromptCacheTtl", tab: 1, kind: Choice(&["5m", "1h"]), scope: "Any file", tui: false, help: "Choose how long the prompt cache holds the requests Claude Code makes outside the main conversation. This key applies to subagents, workflows, and Claude Code's own background and helper requests, such as compaction and session titles. The one-hour lifetime keeps the cache warm across longer breaks, and the API bills each cache write at a higher rate than at the five-minute lifetime. Requires Claude Code v2.1.242 or later. Default: unset, so each of these requests gets its default lifetime." },
    CcKey { key: "switchModelsOnFlag", tab: 1, kind: Bool, scope: "Any file", tui: false, help: "Choose what happens when a safety classifier flags a request: switch to the fallback model and continue, or pause so you can choose between switching and editing the prompt. Default: unset. Claude Code switches automatically, though it may ask first in an interactive session." },
    CcKey { key: "ultracode", tab: 1, kind: Bool, scope: "Any file", tui: false, help: "Start sessions with ultracode on. With it on, Claude plans a workflow for each substantive task instead of waiting for you to ask. Claude plans workflows only when dynamic workflows are enabled for you and your model supports xhigh effort. The key doesn't change the session's effort level: ultracode runs at whichever level the session uses. Claude Code reads this key but never writes it: /effort ultracode turns ultracode on for the current session only. Default: unset, so ultracode is off." },
    CcKey { key: "autoMode.classifyAllShell", tab: 2, kind: Bool, scope: "User or managed", tui: false, help: "Send every Bash and PowerShell command through the auto mode classifier while auto mode is active. By default, auto mode suspends only allow rules that could run arbitrary code: tool-wide and wildcard rules such as Bash(*), and interpreter or shell-wrapper prefixes such as Bash(python *). A command that any other allow rule matches, such as Bash(npm test), skips the classifier unless it carries per-command allowed domains. When it skips, a destructive argument the rule's prefix didn't anticipate can get through unseen. Setting this key suspends every shell allow rule for the session so the classifier sees every command. Requires Claude Code v2.1.193 or later. Default: false." },
    CcKey { key: "disableAutoMode", tab: 2, kind: Choice(&["disable"]), scope: "Any file", tui: false, help: "Remove auto mode from the Shift+Tab cycle. Any session that would otherwise start in auto mode, whether from --permission-mode auto, a settings file, or the built-in default, starts in default instead. Administrators set it in managed settings to prevent developers in their organization from using auto mode. Default: unset." },
    CcKey { key: "useAutoModeDuringPlan", tab: 2, kind: Bool, scope: "User, local, or managed", tui: false, help: "Choose whether Claude Code uses the auto mode classifier to review shell commands in plan mode. With the default true, the classifier reviews each command during planning when auto mode is available and you see no prompt, except for critical-path removals. Set false to get a permission prompt for every command outside the built-in read-only set. Appears in /config as Use auto mode during plan. Default: true." },
    CcKey { key: "permissions.allow", tab: 2, kind: Json, scope: "Any file", tui: false, help: "List the tool uses Claude Code approves without asking you. In an MCP rule, * can appear only in the tool name after the mcp__<server>__ prefix, such as mcp__github__get_*; it can't appear in the server name. Default: unset." },
    CcKey { key: "permissions.ask", tab: 2, kind: Json, scope: "Any file", tui: false, help: "List the tool uses that prompt you for confirmation even in a permission mode that would otherwise approve them, such as acceptEdits or bypassPermissions. In dontAsk mode Claude Code denies a matching tool use instead of prompting. Default: unset." },
    CcKey { key: "permissions.deny", tab: 2, kind: Json, scope: "Any file", tui: false, help: "List the tool uses Claude Code blocks. Use it for files that hold API keys, secrets, or environment values: Claude Code excludes matching files from file discovery and search results, denies reads of them, and blocks the Edit and Write tools on the matching paths. Default: unset." },
    CcKey { key: "permissions.additionalDirectories", tab: 2, kind: Json, scope: "Any file", tui: false, help: "Give Claude file access to directories outside the one you started in, as additional working directories. Most .claude/ configuration is not discovered from these directories. Default: unset." },
    CcKey { key: "permissions.blockReadsOutsideWorkingDirectories", tab: 2, kind: Bool, scope: "Any file", tui: false, help: "Make Claude's file tools refuse reads outside your working directories in every permission mode, including bypassPermissions. Claude Code denies Read, Grep, Glob, and LSP calls on those paths and tells Claude to ask you to add the directory with /add-dir. Files Claude Code itself needs stay readable, such as your skills, plugins, rules, agents, commands, and the CLAUDE.md memory file under ~/.claude/. Requires Claude Code v2.1.257 or later. Default: unset, so reads outside the working directories follow your permission mode." },
    CcKey { key: "permissions.defaultMode", tab: 2, kind: Choice(&["default", "acceptEdits", "plan", "auto", "dontAsk", "bypassPermissions", "manual"]), scope: "Any file", tui: false, help: "Set the permission mode new sessions start in. When you leave it unset, sessions start in the built-in default for your surface. Default: unset." },
    CcKey { key: "permissions.disableBypassPermissionsMode", tab: 2, kind: Choice(&["disable"]), scope: "Any file", tui: false, help: "Prevent anyone from entering bypassPermissions mode. Claude Code then rejects the --dangerously-skip-permissions flag, and ignores an agent definition's permissionMode: bypassPermissions, so the subagent runs with the parent session's permission mode. Default: unset." },
    CcKey { key: "skipAutoPermissionPrompt", tab: 2, kind: Bool, scope: "User or managed", tui: false, help: "Skip the one-time notice describing auto mode that Claude Code shows when you first enter auto mode yourself, for example through your own settings or the mode selector, rather than when the built-in default starts a session in it. Claude Code shows that notice once and then records that it was shown, so this key only matters where the notice hasn't appeared yet. Default: unset, so the notice appears once." },
    CcKey { key: "skipDangerousModePermissionPrompt", tab: 2, kind: Bool, scope: "User, local, or managed", tui: false, help: "Skip the confirmation dialog Claude Code shows before a session enters bypassPermissions mode, whether from --dangerously-skip-permissions or from defaultMode: \"bypassPermissions\". Claude Code writes true here in your user settings when you accept that dialog once. Default: unset, so the dialog appears." },
    CcKey { key: "sandbox.enabled", tab: 3, kind: Bool, scope: "Any file", tui: false, help: "Turn on sandboxing for Bash commands. When you pick a mode in the /sandbox panel, Claude Code writes this key to .claude/settings.local.json for the current project; set it in ~/.claude/settings.json to sandbox every project. Default: false." },
    CcKey { key: "sandbox.failIfUnavailable", tab: 3, kind: Bool, scope: "Any file", tui: false, help: "Make Claude Code exit with an error at startup when sandbox.enabled is true but the sandbox can't start, because a dependency is missing or the platform is unsupported. Without this key, Claude Code runs commands unsandboxed. Managed deployments that require sandboxing as a security gate can use this setting. Default: false." },
    CcKey { key: "sandbox.autoAllowBashIfSandboxed", tab: 3, kind: Bool, scope: "Any file", tui: false, help: "Let Claude Code run sandboxed Bash commands without a permission prompt. Commands that can't run in the sandbox still go through the regular permission flow, and deny rules and content-scoped ask rules such as Bash(git push *) still apply; a bare Bash ask rule is skipped for sandboxed commands. Set it to false to send sandboxed commands through the regular permission flow too, which the /sandbox Mode tab calls regular permissions mode. Default: true." },
    CcKey { key: "sandbox.excludedCommands", tab: 3, kind: Json, scope: "Any file", tui: false, help: "Name commands that Claude Code runs outside the sandbox, such as tools that don't work under it. Each entry uses the same syntax as the content of a Bash(...) permission rule: an exact command, a prefix such as docker *, or a wildcard pattern. A pattern with no wildcard is an exact match, so docker matches only docker with no arguments. Default: unset, so no command is excluded." },
    CcKey { key: "sandbox.allowUnsandboxedCommands", tab: 3, kind: Bool, scope: "Any file", tui: false, help: "Let Claude retry a command outside the sandbox with the dangerouslyDisableSandbox parameter after the sandbox blocks it. When it's false, Claude Code ignores that parameter. While the sandbox is running, commands Claude runs are then sandboxed unless they match an excludedCommands entry. The /sandbox Overrides tab shows that state as Strict sandbox mode. A false in managed settings turns on strict sandbox mode for the developers it covers. Default: true." },
    CcKey { key: "sandbox.filesystem.allowWrite", tab: 3, kind: Json, scope: "Any file", tui: false, help: "Add paths where sandboxed commands can write, beyond the working directory, the per-user temp directory, and the directories you've added with --add-dir, /add-dir, or permissions.additionalDirectories. Use it when a subprocess such as kubectl or a build tool needs to write outside the project. Default: unset, so sandboxed commands can write to the working directory, the per-user temp directory, directories you've added with --add-dir or /add-dir, and directories in permissions.additionalDirectories." },
    CcKey { key: "sandbox.filesystem.denyWrite", tab: 3, kind: Json, scope: "Any file", tui: false, help: "Block sandboxed commands from writing to specific paths, including paths inside a directory that is otherwise writable. Default: unset." },
    CcKey { key: "sandbox.filesystem.denyRead", tab: 3, kind: Json, scope: "Any file", tui: false, help: "Block sandboxed commands from reading specific paths, such as credential files that the default read policy would otherwise expose. To protect a credential file and keep it usable through the sandbox proxy, see sandbox.credentials instead. Default: unset, so sandboxed commands keep the default read access, which includes credential files such as ~/.aws/credentials." },
    CcKey { key: "sandbox.filesystem.allowRead", tab: 3, kind: Json, scope: "Any file", tui: false, help: "Re-open reading for specific paths inside a region that denyRead blocks, to build workspace-only read access. An exact or wildcard denyRead entry stays blocked inside a broader allowRead, as the overlap table shows. When a wildcard denyRead entry such as ~//.env matches a directory, Claude Code blocks reads of its contents as well. Before v2.1.236 on macOS, Claude Code re-opened the paths a wildcard denyRead entry matched wherever a broader allowRead entry covered them, and left a matched directory's contents readable. Default: unset." },
    CcKey { key: "sandbox.filesystem.disabled", tab: 3, kind: Bool, scope: "User or managed", tui: false, help: "Skip filesystem isolation while keeping network isolation. Sandboxed commands get unrestricted read and write access to the host filesystem, and their network egress stays confined to network.allowedDomains. Use it when you sandbox to control where commands connect rather than what they write. Default: false, so filesystem isolation stays on." },
    CcKey { key: "sandbox.ignoreViolations", tab: 3, kind: Json, scope: "Any file", tui: false, help: "Silence sandbox violation reports for paths you expect a command to probe and be refused, such as a tool that checks /etc/hosts on startup, so those denials don't show up as violations or in what Claude sees. The sandbox still blocks the access; only the report is suppressed. Keys are substrings to match against the command, with * matching every command, and values are substrings of the violation to ignore for that command, such as a filesystem path. Default: unset, so every violation is reported." },
    CcKey { key: "sandbox.enableWeakerNestedSandbox", tab: 3, kind: Bool, scope: "Any file", tui: false, help: "Run the Linux sandbox inside an unprivileged Docker container, where bubblewrap can't mount a fresh /proc. Instead the inner sandbox bind-mounts the container's existing /proc, which exposes process information that a fresh mount would hide. This reduces security; use it only when the outer container already provides the isolation you need. Default: false." },
    CcKey { key: "sandbox.enableWeakerNetworkIsolation", tab: 3, kind: Bool, scope: "Any file", tui: false, help: "Let sandboxed commands on macOS reach the system TLS trust service, com.apple.trustd.agent. Go-based tools such as gh, gcloud, and terraform need it to verify TLS certificates when you use network.httpProxyPort with a MITM proxy and a custom CA. This reduces security by opening a potential data exfiltration path through the trust service. Default: false." },
    CcKey { key: "sandbox.allowAppleEvents", tab: 3, kind: Bool, scope: "User or managed", tui: false, help: "Let sandboxed commands on macOS send Apple Events, which open, osascript, and tools that open URLs in a browser need; without it they fail with error -600. This removes code-execution isolation: sandboxed commands can launch other applications unsandboxed with no user prompt, and can send AppleScript commands to running applications such as Terminal, subject to the per-app macOS automation-consent prompt (TCC). Default: false." },
    CcKey { key: "sandbox.allowNestedUserNamespaces", tab: 3, kind: Bool, scope: "User or managed", tui: false, help: "Let sandboxed commands on Linux and WSL2 create user namespaces, which Chromium's and Electron's own sandbox, a nested bubblewrap, and unshare need. If you set this key to true, you turn off a security boundary: code from a sandboxed command can end up running outside the sandbox. For rootless Podman or Buildah, use excludedCommands instead, because the sandbox stops them in other ways too. Requires Claude Code v2.1.305 or later. Default: false." },
    CcKey { key: "sandbox.ripgrep", tab: 3, kind: Json, scope: "User or managed", tui: false, help: "Point the sandbox at a ripgrep binary of your own instead of the one Claude Code uses, for example when your platform needs a differently built rg. Default: unset, so the sandbox uses the same ripgrep binary as Claude Code. That is the bundled binary unless you set USE_BUILTIN_RIPGREP to 0." },
    CcKey { key: "sandbox.credentials.files", tab: 3, kind: Json, scope: "Any file", tui: false, help: "Protect credential files or directories from sandboxed commands. With \"mode\": \"deny\", Claude Code blocks reads of the path inside the sandbox, the same read block as sandbox.filesystem.denyRead. With \"mode\": \"mask\", sandboxed commands on Linux and WSL2 read a sentinel copy of the file, and the sandbox proxy substitutes the real value on outbound requests to that entry's injectHosts; on macOS the file is unreadable inside the sandbox instead. \"mode\": \"mask\" requires Claude Code v2.1.221 or later. Default: unset, so no credential files are protected." },
    CcKey { key: "sandbox.credentials.envVars", tab: 3, kind: Json, scope: "Any file", tui: false, help: "Protect environment variables from sandboxed commands. With \"mode\": \"deny\", Claude Code removes the variable from the environment of sandboxed commands. With \"mode\": \"mask\", sandboxed commands see a per-session sentinel value, and the sandbox proxy substitutes the real value on outbound requests to that entry's injectHosts, so tools such as gh and npm keep authenticating without ever holding the real credential. Default: unset, so no environment variables are protected." },
    CcKey { key: "sandbox.credentials.allowPlaintextInject", tab: 3, kind: Bool, scope: "User or managed", tui: false, help: "Allow mask substitution on plain HTTP requests as well as TLS-terminated HTTPS. On plain HTTP the upstream identity is unverified and the credential travels in cleartext, so leave this off outside trusted test networks. Default: false." },
    CcKey { key: "sandbox.credentials.awsPairs", tab: 3, kind: Json, scope: "User or managed", tui: false, help: "Group masked environment variables that form one AWS credential for SigV4 re-signing when your credential lives in variables with non-standard names. Claude Code links the conventional AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY, and AWS_SESSION_TOKEN trio automatically when you mask their whole values, so you need this key only for other names. Requires Claude Code v2.1.224 or later. Default: unset, so only the conventional trio is paired." },
    CcKey { key: "sandbox.credentials.sigv4", tab: 3, kind: Json, scope: "User or managed", tui: false, help: "Choose what the sandbox proxy does with AWS request forms it can't re-sign: streaming for aws-chunked streaming uploads, presigned for presigned URLs, and sigv4a for SigV4A asymmetric signatures. This applies only to requests signed with a masked pair's placeholder access key ID. Requires Claude Code v2.1.224 or later. Default: unset, so every form is \"deny\"." },
    CcKey { key: "sandbox.network.allowUnixSockets", tab: 3, kind: Json, scope: "Any file", tui: false, help: "List the Unix socket paths sandboxed commands can connect to on macOS. Claude Code ignores this list on Linux and WSL2, where the seccomp filter can't inspect socket paths; use allowAllUnixSockets there instead. Default: unset, so the macOS sandbox blocks every Unix socket." },
    CcKey { key: "sandbox.network.allowAllUnixSockets", tab: 3, kind: Bool, scope: "Any file", tui: false, help: "Let sandboxed commands connect to every Unix socket. On Linux and WSL2, the sandbox's seccomp filter blocks socket(AF_UNIX, ...) calls, so this is the only way to permit Unix sockets there. When the filter is missing, which /sandbox reports on its Dependencies tab, the sandbox doesn't block Unix-socket calls. See Set up Linux and WSL2 for where the filter comes from. Default: false." },
    CcKey { key: "sandbox.network.allowLocalBinding", tab: 3, kind: Bool, scope: "Any file", tui: false, help: "Let sandboxed commands on macOS listen on network ports, for example to start a dev server, and connect to any port on localhost. A command that listens on a non-loopback address accepts connections from other machines. The key has no effect on Linux and WSL2, where each sandboxed command has its own loopback interface. To reach a server on the host from Linux or WSL2, see A command fails to reach a server on localhost. Default: false." },
    CcKey { key: "sandbox.network.allowMachLookup", tab: 3, kind: Json, scope: "Any file", tui: false, help: "List additional XPC and Mach service names the macOS sandbox may look up. Tools that communicate over XPC, such as the iOS Simulator or Playwright, need their services listed here. Default: unset." },
    CcKey { key: "sandbox.network.allowedDomains", tab: 3, kind: Json, scope: "Any file", tui: false, help: "Pre-allow domains for outbound traffic from sandboxed commands, so the sandbox doesn't prompt for them. Wildcards such as *.example.com match subdomains, and an optional :port suffix limits an entry to one port; an entry without a port matches every port. Default: unset, so your permission mode decides what happens to each new host." },
    CcKey { key: "sandbox.network.deniedDomains", tab: 3, kind: Json, scope: "Any file", tui: false, help: "Block domains for outbound traffic from sandboxed commands, using the same wildcard, port, and IPv6 syntax as allowedDomains. A denied domain stays blocked even when an allowedDomains entry matches it too. Default: unset." },
    CcKey { key: "sandbox.network.strictAllowlist", tab: 3, kind: Bool, scope: "User or managed", tui: false, help: "Deny sandboxed commands access to hosts outside the allowlist instead of prompting for approval. The allowlist is allowedDomains plus domains from WebFetch(domain:...) allow rules, or only the managed settings entries when allowManagedDomainsOnly is set. Locks that apply without an admin-required sandbox covers a repository's entries. Requires Claude Code v2.1.219 or later. Default: false." },
    CcKey { key: "sandbox.network.httpProxyPort", tab: 3, kind: Number, scope: "Any file", tui: false, help: "Point the sandbox at your own HTTP proxy instead of the one Claude Code runs. Organizations do this to inspect HTTPS traffic, apply their own filtering rules, or log requests. Your proxy takes over filtering, and Claude Code stops applying its domain lists and network prompts to traffic sent there. When unset, Claude Code starts its own proxy for HTTP traffic. Default: unset, so Claude Code runs its own proxy." },
    CcKey { key: "sandbox.network.socksProxyPort", tab: 3, kind: Number, scope: "Any file", tui: false, help: "Point the sandbox at your own SOCKS5 proxy instead of the one Claude Code runs. Your proxy takes over filtering, and Claude Code stops applying its domain lists and network prompts to traffic sent there. When unset, Claude Code starts its own proxy for SOCKS traffic. Default: unset, so Claude Code runs its own proxy." },
    CcKey { key: "sandbox.network.tlsTerminate", tab: 3, kind: Json, scope: "User or managed", tui: false, help: "Make the sandbox proxy terminate TLS so it can read the contents of HTTPS requests. This is experimental, and mask credential substitution requires it. Set {} to generate an ephemeral certificate authority for the session, or set caCertPath and caKeyPath to use your own. Default: unset, so the proxy doesn't terminate or inspect TLS." },
    CcKey { key: "autoCompactEnabled", tab: 4, kind: Bool, scope: "Any file", tui: false, help: "Have Claude Code compact the conversation automatically when context approaches the limit. Appears in /config as Auto-compact, and toggling it there writes this key to your user settings. Default: true." },
    CcKey { key: "autoCompactWindow", tab: 4, kind: Number, scope: "Any file", tui: false, help: "Set how full the context window gets before Claude Code compacts automatically. Default: unset, so Claude Code picks a window tuned for your model." },
    CcKey { key: "autoMemoryDirectory", tab: 4, kind: Text, scope: "Any file", tui: false, help: "Store auto memory in a directory of your choice instead of the per-project default. Default: unset, so Claude Code uses ~/.claude/projects/<project>/memory/." },
    CcKey { key: "autoMemoryEnabled", tab: 4, kind: Bool, scope: "Any file", tui: false, help: "Turn auto memory on or off. When false, Claude doesn't read from or write to the auto memory directory. You can also toggle it with /memory during a session, which writes this key to your user settings. Default: true." },
    CcKey { key: "bashOutputMaxChars", tab: 4, kind: Number, scope: "Any file", tui: false, help: "Set how many characters of a successful Bash or PowerShell command's output Claude receives inline. When output passes the limit, Claude Code saves it to a file and Claude receives a short preview plus the file's path. Raise the limit when command output, such as a verbose build or a full test-suite log, routinely overflows the default and you want Claude to read it without opening the file. Requires Claude Code v2.1.261 or later. Default: unset, so Claude receives up to 30,000 characters inline." },
    CcKey { key: "claudeMdExcludes", tab: 4, kind: Json, scope: "Any file", tui: false, help: "Skip specific CLAUDE.md files when Claude Code loads memory. In a large monorepo, use it to skip CLAUDE.md files from other teams that aren't relevant to your work; Exclude irrelevant CLAUDE.md files in the large-codebases guide walks through that case. Patterns match against absolute file paths. Default: unset, so Claude Code loads every CLAUDE.md it finds." },
    CcKey { key: "env", tab: 4, kind: Json, scope: "Any file", tui: false, help: "Set environment variables for every session and for the subprocesses Claude Code starts from it. Most variables in the environment variables reference can go here, which is how you apply one to every session or roll it out to your team. Project and local settings can't set some of them. Default: unset." },
    CcKey { key: "fileCheckpointingEnabled", tab: 4, kind: Bool, scope: "Any file", tui: false, help: "Have Claude Code snapshot files before each edit so /rewind can restore them. Appears in /config as Rewind code (checkpoints), and toggling it there writes this key to your user settings. Default: true." },
    CcKey { key: "idleCompaction", tab: 4, kind: Bool, scope: "Any file", tui: false, help: "Idle compaction compacts a long conversation that you've stepped away from. Your next message then sends a summary instead of the whole conversation. Once compacted, the conversation shows a notice: Default: true." },
    CcKey { key: "plansDirectory", tab: 4, kind: Text, scope: "Any file", tui: false, help: "Choose where Claude Code stores the plan files it writes in plan mode. Claude Code resolves the path relative to the project root. Default: unset, so Claude Code uses ~/.claude/plans." },
    CcKey { key: "skillListingBudgetFraction", tab: 4, kind: Number, scope: "Any file", tui: false, help: "Each turn, Claude sees a listing of your skills with their descriptions, and Claude Code caps that listing at a share of the context window. When the listing is over the cap, Claude Code keeps every skill's name but drops the descriptions of the least-used skills, so Claude can still invoke those skills but is less likely to choose one on its own. Raise this key to keep more descriptions visible at the cost of more context per turn. Default: 0.01, which reserves 1% of the context window." },
    CcKey { key: "skillListingMaxDescChars", tab: 4, kind: Number, scope: "Any file", tui: false, help: "Each turn, Claude sees a listing of your skills that shows each skill's description and when_to_use text. This key caps how many characters of that text Claude Code shows per skill; longer text is cut at the cap. Default: 1536." },
    CcKey { key: "askUserQuestionTimeout", tab: 5, kind: Choice(&["60s", "5m", "10m", "never"]), scope: "User or managed", tui: false, help: "Let an unanswered AskUserQuestion dialog auto-continue after a period of idle time, submitting whatever options you had already selected. Set it when you step away and want Claude to continue without you. With the default, questions wait until you answer them. For when the timer pauses or never starts, see Question auto-continue timeout. Default: \"never\"." },
    CcKey { key: "autoContinueAtUsageLimit", tab: 5, kind: Bool, scope: "User or managed", tui: false, help: "After a claude.ai usage limit stops your session, wait in the open session and continue the task automatically after the reset. See Turn automatic continue off. Requires Claude Code v2.1.234 or later. Default: true." },
    CcKey { key: "autoScrollEnabled", tab: 5, kind: Bool, scope: "Any file", tui: true, help: "Follow new output to the bottom of the conversation in fullscreen rendering. Turn it off to stay where you scrolled while Claude keeps working; permission prompts still scroll into view. Default: true." },
    CcKey { key: "axScreenReader", tab: 5, kind: Bool, scope: "User or managed", tui: true, help: "Render screen-reader friendly output: flat text without decorative borders or animations. Screen-reader mode uses the classic renderer, so the tui setting has no effect while it is active; attached background sessions still render fullscreen. Default: unset, so screen-reader mode is off." },
    CcKey { key: "bashEditDiffEnabled", tab: 5, kind: Bool, scope: "User or managed", tui: true, help: "Choose whether Claude Code records which files changed in a Git repository while a Bash command runs. When it records them, you see their diff in the terminal after the command, and your PostToolUse Bash hooks receive the changed-file list. Default: unset, so Claude Code records changes in auto mode and bypassPermissions mode when it directs Claude to edit files through Bash." },
    CcKey { key: "companyAnnouncements", tab: 5, kind: Json, scope: "Any file", tui: true, help: "Show your organization's announcements to users at startup. When you list more than one, Claude Code picks one at random for each session; on a person's very first launch it shows the first entry. Default: unset, so no announcement shows." },
    CcKey { key: "defaultShell", tab: 5, kind: Choice(&["bash", "powershell"]), scope: "Any file", tui: false, help: "Choose whether Bash or PowerShell runs the shell commands you type with the ! prefix in the input box, the ones Claude Code runs directly and adds to the session. Default: \"bash\", or \"powershell\" on Windows when Bash isn't available." },
    CcKey { key: "dialogExpiry", tab: 5, kind: Choice(&["60s", "5m", "10m", "never"]), scope: "User or managed", tui: false, help: "Set the deadline for dialogs Claude Code forwards to a remote client, such as a Remote Control or SDK host, and for the approval dialog for a held cross-session message. On Claude Code v2.1.236 or later, the same deadline bounds the mid-session Fable usage-credits consent prompt in a session that may have nobody at the terminal. When no answer arrives before the deadline, Claude Code cancels the dialog and continues with its no-action default. Requires Claude Code v2.1.224 or later. Default: \"5m\"." },
    CcKey { key: "editorMode", tab: 5, kind: Choice(&["normal", "vim"]), scope: "Any file", tui: true, help: "Choose the key binding mode for the input prompt. Default: \"normal\"." },
    CcKey { key: "emojiCompletionEnabled", tab: 5, kind: Bool, scope: "Any file", tui: true, help: "Show emoji suggestions when you type : plus a shortcode in the prompt input, and replace a completed shortcode such as :heart: with its emoji. Set it to false to turn off both. Default: true." },
    CcKey { key: "fileSuggestion", tab: 5, kind: Json, scope: "Any file", tui: true, help: "Run your own command to supply @ file path autocomplete instead of the built-in file suggestion. The built-in suggestion uses fast filesystem traversal; a large monorepo may do better with project-specific indexing such as a pre-built file index. Default: unset, so Claude Code uses the built-in file suggestion." },
    CcKey { key: "footerLinksRegexes", tab: 5, kind: Json, scope: "User or managed", tui: true, help: "Render extra clickable badges in the footer below the input box when a regex matches turn output: tool results, including file contents and fetched pages, and Claude's own responses. Use it to turn IDs printed by project CLIs, such as review tools and issue trackers, into session links. Default: unset, so no badges render." },
    CcKey { key: "keybindingFlavor", tab: 5, kind: Choice(&["classic", "readline"]), scope: "Any file", tui: true, help: "Warning: Deprecated since v2.1.261 and has no effect. The prompt's word-editing keys always follow readline conventions, as in Bash. Claude Code still accepts keybindingFlavor, so a settings file that sets it stays valid. Default: unset." },
    CcKey { key: "maxProseWidth", tab: 5, kind: Number, scope: "Any file", tui: true, help: "Cap the width of the prose in Claude's responses so lines stay readable in a wide terminal. Paragraphs, headings, lists, and blockquotes wrap within this many columns, while tables and code blocks keep the full terminal width. Requires Claude Code v2.1.282 or later. Default: unset, so prose wraps at the terminal edge." },
    CcKey { key: "prefersReducedMotion", tab: 5, kind: Bool, scope: "Any file", tui: true, help: "Reduce or turn off interface animations such as the spinner, shimmer, and flash effects. Appears in /config as Reduce motion. Default: false." },
    CcKey { key: "promptSuggestionEnabled", tab: 5, kind: Bool, scope: "Any file", tui: true, help: "Show or hide prompt suggestions, the grayed-out predictions that appear in your prompt input. Set it to false, or turn off Prompt suggestions in /config, to hide them. Default: true." },
    CcKey { key: "respectGitignore", tab: 5, kind: Bool, scope: "Any file", tui: false, help: "Control whether the @ file picker leaves out files that match .gitignore patterns. Appears in /config as Respect .gitignore in file picker. Default: true." },
    CcKey { key: "respondToBashCommands", tab: 5, kind: Bool, scope: "Any file", tui: false, help: "Choose whether Claude responds after you run a shell command with the ! prefix in the input box. By default, Claude Code adds the command's output to the conversation and Claude replies to it. Set this key to false to add the output to context without a reply, so you can run several commands and ask about them together. Default: true." },
    CcKey { key: "showClearContextOnPlanAccept", tab: 5, kind: Bool, scope: "Any file", tui: true, help: "When Claude finishes a plan in plan mode, it shows an approval menu. Planning can use a lot of context, so this key adds a first option to that menu, Yes, clear context and …, that approves the plan, clears the conversation context, and starts implementing from the plan alone. The rest of the label names the permission mode the session continues in, and shows how much of your context the planning used. Default: false." },
    CcKey { key: "showTurnDuration", tab: 5, kind: Bool, scope: "Any file", tui: true, help: "Show or hide the turn duration message after each response, such as \"Cooked for 1m 6s · done 6:05 PM\". The clock after \"done\" shows when the turn finished; timeFormat and timeZone control its format and zone. Appears in /config as Show turn duration. Default: true." },
    CcKey { key: "spellcheck", tab: 5, kind: Json, scope: "User or managed", tui: true, help: "Underline misspelled words in the prompt input as you type, using a spell checker you install. Claude Code checks only the text in the input box. Check spelling as you type covers installing aspell, hunspell, or ispell and what the checker covers. Requires Claude Code v2.1.235 or later. Default: unset, so spell checking is off; checker defaults to \"auto\", the first of the three found on PATH; language defaults to the checker's own dictionary; color defaults to the theme's error color." },
    CcKey { key: "spinnerTipsEnabled", tab: 5, kind: Bool, scope: "Any file", tui: true, help: "While Claude works, the spinner line rotates through short tips about Claude Code features, such as \"Use Plan Mode to prepare for a complex request before making changes. Press Shift+Tab twice to enable.\" Set this key to false to hide them. Appears in /config as Show tips. Default: true." },
    CcKey { key: "spinnerTipsOverride", tab: 5, kind: Json, scope: "Any file", tui: true, help: "Add your own tips to the spinner tips that Claude Code shows while Claude works, or replace the built-in tips with yours. Claude Code puts your tips in the same rotation as the built-in ones. Default: unset, so Claude Code shows only the built-in tips." },
    CcKey { key: "spinnerVerbs", tab: 5, kind: Json, scope: "Any file", tui: true, help: "While a turn is in progress, the spinner shows a rotating verb such as \"Accomplishing\", \"Architecting\", or \"Baking\". Use this key to add your own verbs to that rotation or replace the built-in list with yours. Default: unset, so Claude Code uses the built-in verbs." },
    CcKey { key: "statusLine", tab: 5, kind: Json, scope: "Any file", tui: false, help: "Run your own command to render a status line below the prompt with context such as the model, cost, or git branch. Optional fields adjust spacing, add periodic re-runs, and hide the built-in vim mode indicator when your script renders vim.mode itself. Default: unset, so no status line." },
    CcKey { key: "subagentStatusLine", tab: 5, kind: Json, scope: "Any file", tui: true, help: "When Claude runs subagents, Claude Code lists them in a task display below the prompt, one row per subagent showing name · description · token count. This key lets you run your own command to rewrite those rows, for example to show each subagent's context usage as a percentage. On each refresh, Claude Code sends the visible rows as one JSON object on stdin, with a tasks array carrying each subagent's id, name, status, model, tokenCount, and more, and replaces the row for each id you write back as a {\"id\", \"content\"} line. Rows you don't write back keep the default rendering. Default: unset, so Claude Code renders the default rows." },
    CcKey { key: "syntaxHighlightingDisabled", tab: 5, kind: Bool, scope: "Any file", tui: true, help: "Claude Code colors code by language in the diffs, code blocks, and file previews it shows in the terminal, with its built-in highlighter; no plugin or language server is involved. Set this key to true to show them as plain text instead, for example if the colors clash with your terminal theme or slow a screen reader. Default: false." },
    CcKey { key: "terminalProgressBarEnabled", tab: 5, kind: Bool, scope: "Any file", tui: true, help: "Some terminals can show a progress indicator on the tab or in the taskbar for the program running in them. While Claude is working, Claude Code reports an in-progress state to the terminal, so you can see from another tab or window whether the session is still busy. The indicator stays visible after the turn ends while background subagents or dynamic workflows are still running, and clears once the session is idle. Default: true." },
    CcKey { key: "terminalTitleFromRename", tab: 5, kind: Bool, scope: "Any file", tui: true, help: "Claude Code sets your terminal tab's title. By default it uses a title it generates from the conversation, and once you give the session a name with /rename or --name, the tab shows that name instead. Set this key to false to keep the generated title on the tab even after you name the session. The name itself still applies, so /resume <name> and the session picker find it. Default: true." },
    CcKey { key: "theme", tab: 5, kind: Choice(&["auto", "dark", "light", "dark-daltonized", "light-daltonized", "dark-ansi", "light-ansi"]), scope: "Any file", tui: true, help: "Pick the color theme for the interface. Appears in /config as Theme. Default: \"dark\"." },
    CcKey { key: "timeFormat", tab: 5, kind: Choice(&["auto", "12-hour", "24-hour", "24-hour-utc"]), scope: "Any file", tui: true, help: "Choose how Claude Code writes the times it shows in the interface, such as the done 6:05 PM at the end of each turn duration message and the timestamps in the transcript viewer. To pick a preset, run /config and set Time format. Requires Claude Code v2.1.257 or later. Default: \"auto\"." },
    CcKey { key: "timeZone", tab: 5, kind: Text, scope: "Any file", tui: true, help: "Show the times in the interface in a time zone other than your system's. Set it to an IANA time zone name, such as \"UTC\" or \"Europe/Dublin\". The times that timeFormat controls then show in this zone. If timeFormat is \"24-hour-utc\", times stay in UTC and Claude Code ignores this key. /config has no row for this key, so set it in a settings file. Requires Claude Code v2.1.257 or later. Default: unset, so times show in your system time zone." },
    CcKey { key: "tui", tab: 5, kind: Choice(&["default", "fullscreen"]), scope: "Any file", tui: true, help: "Choose the terminal UI renderer. Use \"fullscreen\" for the flicker-free alt-screen renderer with virtualized scrollback, or \"default\" for the classic main-screen renderer. Running /tui fullscreen or /tui default writes this key for you. Default: unset, so Claude Code picks the renderer for you." },
    CcKey { key: "verbose", tab: 5, kind: Bool, scope: "Any file", tui: true, help: "By default, the transcript collapses each tool call to a short summary, such as the command Claude ran and a line count of its output, and you press Ctrl+O to switch the whole transcript to the expanded view when you want the details. Set this key to true to show every tool call's full input and output inline as it happens, which is useful when you're debugging a hook, an MCP server, or a long shell command. Appears in /config as Verbose output. Default: false." },
    CcKey { key: "viewMode", tab: 5, kind: Choice(&["default", "verbose", "focus"]), scope: "Any file", tui: true, help: "Set the transcript view Claude Code starts in: \"default\", \"verbose\", or \"focus\". When set, it overrides both the sticky /focus selection and the verbose setting. Default: unset, so the verbose setting and your last /focus choice apply." },
    CcKey { key: "vimInsertModeRemaps", tab: 5, kind: Json, scope: "User or managed", tui: true, help: "Map two-key INSERT-mode sequences to Escape in vim editor mode. Each key is exactly two printable characters typed in sequence, and \"<Esc>\" is the only supported target; Claude Code ignores other entries. Default: unset." },
    CcKey { key: "voice", tab: 5, kind: Json, scope: "Any file", tui: true, help: "Turn on voice dictation and choose how the dictation key behaves. Claude Code writes this object for you when you run /voice. Default: unset, so dictation is off; when enabled is true and mode is unset, Claude Code uses \"hold\"." },
    CcKey { key: "voiceEnabled", tab: 5, kind: Bool, scope: "Any file", tui: true, help: "Warning: Deprecated since v2.1.92, when the voice object replaced it. Claude Code still reads it so older settings files keep working, but new configurations should set voice.enabled. Default: unset." },
    CcKey { key: "wheelScrollAccelerationEnabled", tab: 5, kind: Bool, scope: "Any file", tui: true, help: "Accelerate mouse-wheel scroll speed during fast scrolls in fullscreen rendering. Set it to false for a constant scroll rate per wheel notch. Default: true." },
    CcKey { key: "includeCoAuthoredBy", tab: 6, kind: Bool, scope: "Any file", tui: false, help: "Warning: Deprecated since v2.0.62, when attribution replaced it. Claude Code still reads it, but new configurations should set attribution. Default: true." },
    CcKey { key: "includeGitInstructions", tab: 6, kind: Bool, scope: "Any file", tui: false, help: "Claude Code gives Claude two git-related pieces of context: its built-in instructions for how to write commits and pull requests, in the Bash tool's description, and a git status snapshot of your repository. The snapshot holds the current branch, the main branch, git status output, and recent commits. Claude Code reads it when a conversation starts. Default: true." },
    CcKey { key: "prUrlTemplate", tab: 6, kind: Text, scope: "Any file", tui: false, help: "Point the PR links Claude Code renders, in the footer badge and in tool-result summaries, at an internal code-review tool instead of github.com. Claude Code substitutes {host}, {owner}, {repo}, {number}, and {url} from the PR URL. GitLab merge request links on both surfaces keep their GitLab URL. Default: unset." },
    CcKey { key: "attribution.commit", tab: 6, kind: Text, scope: "Any file", tui: false, help: "Set the attribution text Claude Code adds to git commits, including any trailers. Set it to an empty string to hide commit attribution. Default: unset, so Claude Code adds Co-Authored-By: <name> <noreply@anthropic.com>. The name is the model in use when the commit is made, such as Claude Sonnet 5. When a subagent makes the commit, the trailer names the subagent's model." },
    CcKey { key: "attribution.pr", tab: 6, kind: Text, scope: "Any file", tui: false, help: "Set the attribution text Claude Code adds to pull request descriptions. Set it to an empty string to hide pull request attribution. Default: unset, so Claude Code adds 🤖 Generated with Claude Code." },
    CcKey { key: "attribution.sessionUrl", tab: 6, kind: Bool, scope: "Any file", tui: false, help: "Choose whether Claude Code appends the claude.ai session link when it commits or opens a pull request from a cloud or Remote Control session. Claude Code adds the link as a Claude-Session trailer on commits and as a link in pull request descriptions. Set it to false to omit the link. Default: true." },
    CcKey { key: "allowedHttpHookUrls", tab: 7, kind: Json, scope: "Any file", tui: false, help: "Limit which URLs HTTP hooks can target. When you define this key, Claude Code runs an HTTP hook only if its URL matches one of the patterns and blocks the rest without running them; an empty array blocks every HTTP hook. Default: unset, so any URL is allowed." },
    CcKey { key: "disableAllHooks", tab: 7, kind: Bool, scope: "Any file", tui: false, help: "Turn off hooks, any custom status line, and any custom file suggestion command. Use it to turn all of these off temporarily without deleting them from your settings. Default: unset, so hooks run." },
    CcKey { key: "disableWorkflows", tab: 7, kind: Bool, scope: "Any file", tui: false, help: "Turn off dynamic workflows and the bundled workflow commands for everyone your settings reach, such as an organization through managed settings. To turn workflows on or off just for yourself, use enableWorkflows instead, which the Dynamic workflows toggle in /config writes to your user settings. Default: false." },
    CcKey { key: "enableWorkflows", tab: 7, kind: Bool, scope: "Any file", tui: false, help: "Turn dynamic workflows on or off for yourself when your plan's default isn't what you want. Appears in /config as Dynamic workflows, which writes this key to your user settings and removes it again when you toggle back to your plan's default. To turn workflows off for everyone from managed settings, use disableWorkflows instead. Default: unset, so workflows are on unless you're on the Pro plan, where they're off." },
    CcKey { key: "hooks", tab: 7, kind: Json, scope: "Any file", tui: false, help: "Run your own commands, prompts, agents, HTTP requests, or MCP tools as hooks at points in Claude Code's lifecycle, such as before a tool call or when a session starts; the hooks reference lists every event, its payload, and its exit codes. Each event maps to a list of matcher groups, and each group lists the handlers to run when the matcher applies. Default: unset, so no hooks run." },
    CcKey { key: "httpHookAllowedEnvVars", tab: 7, kind: Json, scope: "Any file", tui: false, help: "An HTTP hook can put the value of an environment variable into a request header, for example an Authorization: Bearer $HOOK_TOKEN header, but only for variables the hook lists in its own allowedEnvVars. This key sets an outer limit on that list for every HTTP hook: a hook can use a variable only if both its own allowedEnvVars and this key name it. Use it to stop a hook from reading a secret it shouldn't, even when the hook's definition asks for it. Default: unset, so each hook's own allowedEnvVars list applies." },
    CcKey { key: "workflowKeywordTriggerEnabled", tab: 7, kind: Bool, scope: "Any file", tui: false, help: "Choose whether typing the keyword ultracode in a prompt triggers a dynamic workflow. Set it to false to type the word without triggering one. Default: true." },
    CcKey { key: "workflowSizeGuideline", tab: 7, kind: Choice(&["unrestricted", "small", "medium", "large"]), scope: "Any file", tui: false, help: "Set the agent count Claude aims for in the dynamic workflows it writes. Claude Code sends the value to Claude as advice, not an enforced cap: \"small\" asks for fewer than 5 agents, \"medium\" fewer than 10, and \"large\" fewer than 50. Choose \"small\" when you want to bound what a workflow spends. Default: \"medium\", or \"small\" when you're signed in on a Pro plan with Claude Code v2.1.271 or later." },
    CcKey { key: "disableBundledSkills", tab: 8, kind: Bool, scope: "Any file", tui: false, help: "Turn off the skills and workflows included with Claude Code. Claude Code removes bundled skills and workflows entirely, while built-in commands such as /init stay typable but are hidden from the model. Default: unset, so bundled skills load." },
    CcKey { key: "disableSkillShellExecution", tab: 8, kind: Bool, scope: "Any file", tui: false, help: "Turn off inline shell execution for !... and ! blocks in skills and custom commands from user, project, plugin, or additional-directory sources. Claude Code replaces each command with [shell command execution disabled by policy] instead of running it. Default: unset, so inline shell runs." },
    CcKey { key: "skillOverrides", tab: 8, kind: Json, scope: "Any file", tui: false, help: "Hide or collapse a skill without editing its SKILL.md. Claude Code applies the value under each skill's name to the skill list Claude sees and to your / autocomplete. Default: unset, so every skill is \"on\"." },
    CcKey { key: "syncClaudeAiSkills", tab: 8, kind: Bool, scope: "User, local, or managed", tui: false, help: "Turn off the download of the skills enabled for your claude.ai account. Claude Code downloads them into ~/.claude/skills/synced/ in terminal sessions where you sign in with your claude.ai account, interactive or non-interactive, and in Cowork and cloud sessions. Set false to stop that download and stop loading the skills it already synced. Claude Code honors only false: true is the same as unset and doesn't turn syncing on where it's otherwise off. Default: unset, so sessions signed in with your claude.ai account sync your skills." },
    CcKey { key: "syncClaudeAiPlugins", tab: 8, kind: Bool, scope: "User, local, or managed", tui: false, help: "Turn off the download of the plugins enabled for your claude.ai account. Claude Code downloads them into ~/.claude/plugins/synced/ at the start of terminal sessions where you sign in with your claude.ai account and in Cowork sessions, and loads each one as <name>@synced. Set false to stop that download and stop loading the plugins it already synced. Claude Code honors only false: true is the same as unset and doesn't turn syncing on where it's otherwise off. Requires Claude Code v2.1.273 or later. Default: unset, so sessions signed in with your claude.ai account sync your plugins." },
    CcKey { key: "enabledPlugins", tab: 8, kind: Json, scope: "Any file", tui: false, help: "Turn individual plugins on or off, keyed by plugin-name@marketplace-name. A plugin with no entry at any scope falls back to its defaultEnabled value. When you enable or disable a plugin with /plugin or claude plugin enable, Claude Code writes this key for you. Default: unset, so each plugin follows its defaultEnabled value." },
    CcKey { key: "extraKnownMarketplaces", tab: 8, kind: Json, scope: "Any file", tui: false, help: "Register additional plugin marketplaces by name, so that people who open the repository, or everyone your managed settings reach, get the marketplace without adding it themselves. Claude Code registers each marketplace it doesn't already know. Whether a plugin that enabledPlugins names from it installs depends on the plugin's source and which file enables it; that entry has the rules. Default: unset." },
    CcKey { key: "pluginConfigs", tab: 8, kind: Json, scope: "User or managed", tui: false, help: "Store the non-sensitive answers you give a plugin's userConfig configuration dialog, keyed by plugin ID. Claude Code writes this key to your user settings when you fill in the dialog, so you don't need to edit it by hand. Claude Code stores sensitive options in the macOS Keychain instead, falling back to ~/.claude/.credentials.json when the Keychain rejects the write; on platforms without a supported keychain, it stores them in ~/.claude/.credentials.json. Default: unset." },
    CcKey { key: "prependPlugins", tab: 8, kind: Json, scope: "User or managed", tui: false, help: "List the managed plugins whose mods run before every mod a user installs, in the listed order. When you set this key in managed settings, name sec-default@builtin in the list to keep the built-in guard. In managed settings, Claude Code skips an id whose plugin doesn't count as your organization's. See Install your organization's mods and set the order for those conditions and for how the two ordering keys work together. Default: unset." },
    CcKey { key: "appendPlugins", tab: 8, kind: Json, scope: "User or managed", tui: false, help: "List the managed plugins whose mods run after every mod a user installs, in the listed order. An id listed in both prependPlugins and appendPlugins is prepended. In managed settings, Claude Code skips an id whose plugin doesn't count as your organization's. Default: unset." },
    CcKey { key: "allowedMcpServers", tab: 9, kind: Json, scope: "Any file", tui: false, help: "Allowlist the MCP servers people can add. Claude Code blocks any server that doesn't match an entry wherever it's defined, including plugin servers, servers a user passes with --mcp-config, and servers from claude.ai. Default: unset, so every server is allowed; an empty array blocks every server users add." },
    CcKey { key: "deniedMcpServers", tab: 9, kind: Json, scope: "Any file", tui: false, help: "Block specific MCP servers. Claude Code refuses to load a matching server wherever it's defined, including plugin servers, servers passed with --mcp-config, servers from managed-mcp.json, servers from managedMcpServers, and the claude.ai connectors it fetches itself. In-process type: \"sdk\" servers are exempt; the app that started the session registers them. Default: unset, so no server is blocked; an empty array also blocks nothing." },
    CcKey { key: "disableClaudeAiConnectors", tab: 9, kind: Bool, scope: "Any file", tui: false, help: "Turn off the claude.ai MCP connectors Claude Code fetches itself, so it neither fetches nor connects them. A true in any settings file applies: a checked-in project .claude/settings.json can opt a repository out of those connectors, but a project-level false can't override a user- or managed-level true. Default: false, so Claude Code fetches your connectors." },
    CcKey { key: "disabledMcpjsonServers", tab: 9, kind: Json, scope: "Any file", tui: false, help: "Reject specific servers defined in a project's .mcp.json file so Claude Code never connects them or asks you to approve them. A rejection in any settings file applies, including a project .claude/settings.json checked into the repository. Default: unset." },
    CcKey { key: "enableAllProjectMcpServers", tab: 9, kind: Bool, scope: "Any file", tui: false, help: "Approve every MCP server defined in project .mcp.json files without a prompt. Claude Code writes this key to .claude/settings.local.json when you choose to approve all servers in the approval dialog. Default: unset, so Claude Code asks you to approve each server." },
    CcKey { key: "enabledMcpjsonServers", tab: 9, kind: Json, scope: "Any file", tui: false, help: "Approve specific servers defined in project .mcp.json files so Claude Code connects them without asking. Claude Code writes this key to .claude/settings.local.json when you approve a server in the approval dialog. Default: unset." },
    CcKey { key: "agent", tab: 10, kind: Text, scope: "Any file", tui: false, help: "Run the main thread as a named subagent, so Claude Code applies that subagent's system prompt, tool restrictions, and model to your session. The same key sets the default agent for sessions you dispatch from claude agents. Default: unset, so the main thread runs as Claude Code's default agent." },
    CcKey { key: "crossSessionInbound", tab: 10, kind: Choice(&["accept", "hold", "refuse"]), scope: "Any file", tui: false, help: "Choose what this session does with messages arriving from your other Claude Code sessions. When no value applies, Claude Code decides per message from the two sessions' permission-mode classes. Requires Claude Code v2.1.224 or later. Default: unset, so Claude Code decides per message." },
    CcKey { key: "disableAgentView", tab: 10, kind: Bool, scope: "Any file", tui: false, help: "Turn off background agents and agent view: claude agents, --bg, /background, and the on-demand supervisor. Set it in managed settings to enforce it for an organization. Default: unset, so agent view is available." },
    CcKey { key: "isolatePeerMachines", tab: 10, kind: Bool, scope: "Any file", tui: false, help: "Require your explicit approval before Claude's SendMessage reaches one of your sessions beyond this machine; see Require approval for cross-machine messages. The approval prompt appears even in bypassPermissions mode. Default: unset, so cross-machine messages don't prompt." },
    CcKey { key: "processWrapper", tab: 10, kind: Text, scope: "User or managed", tui: false, help: "On macOS and Linux, place a corporate launcher command in front of the background processes Claude Code starts. Claude Code runs the launcher with its own command line appended, so the launcher must exec into Claude Code; see Run Claude Code behind a corporate launcher for the launcher contract. Requires Claude Code v2.1.210 or later. Default: unset, so background processes start unwrapped." },
    CcKey { key: "teammateMode", tab: 10, kind: Choice(&["in-process", "auto", "tmux", "iterm2"]), scope: "Any file", tui: false, help: "Choose where Claude Code shows agent team teammates: inside your main terminal pane, or in split panes when your terminal supports them. See Choose a display mode. Default: \"in-process\"." },
    CcKey { key: "worktree.baseRef", tab: 10, kind: Choice(&["fresh", "head"]), scope: "Any file", tui: false, help: "Choose which ref new worktrees branch from. \"fresh\" branches from origin/<default-branch> for a clean tree matching the remote; \"head\" branches from your current local HEAD, so unpushed commits and feature-branch state are present in the worktree. Default: \"fresh\"." },
    CcKey { key: "worktree.symlinkDirectories", tab: 10, kind: Json, scope: "Any file", tui: false, help: "Symlink directories from the main repository into each worktree so you don't duplicate large directories on disk. Default: unset, so Claude Code symlinks no directories." },
    CcKey { key: "worktree.sparsePaths", tab: 10, kind: Json, scope: "Any file", tui: false, help: "Check out only the listed directories in each worktree through git sparse-checkout. Claude Code writes only those directories plus root-level files to disk, which is faster in large monorepos; see Check out only the directories you need. Default: unset, so each worktree checks out the whole tree." },
    CcKey { key: "worktree.bgIsolation", tab: 10, kind: Choice(&["worktree", "none"]), scope: "Any file", tui: false, help: "Choose how background sessions isolate their file edits. If you moved a session to the background with ← or /background, that session edits files in place whatever this key says. With \"worktree\", Claude Code blocks Edit and Write in the main checkout until the session calls EnterWorktree; with \"none\", background jobs edit the working copy directly. Set \"none\" for a repository where git worktrees are impractical. Default: \"worktree\"." },
    CcKey { key: "worktree.location", tab: 10, kind: Text, scope: "User", tui: false, help: "Choose the folder on a remote machine where Desktop SSH sessions create their worktrees, instead of <project-root>/.claude/worktrees/. Only the desktop app reads this key: --worktree, the EnterWorktree tool, isolated subagents, and background sessions ignore it. Requires Claude Desktop v1.44121.0 or later. Default: unset, so worktrees go inside the project." },
    CcKey { key: "agentPushNotifEnabled", tab: 11, kind: Bool, scope: "Any file", tui: false, help: "Allow Claude to send a push notification to your phone when it decides one is worth sending, for example when a long task finishes. Claude can send one while Remote Control is connected. Appears in /config as Push when Claude decides. When you change it there, Claude Code also saves the value to your account. Default: false." },
    CcKey { key: "awaySummaryEnabled", tab: 11, kind: Bool, scope: "Any file", tui: false, help: "Show a one-line session recap when you return to the terminal after a few minutes away. Set it to false, or turn off Session recap in /config, to stop the recap. Default: unset, so the recap is on." },
    CcKey { key: "disableArtifact", tab: 11, kind: Bool, scope: "Any file", tui: false, help: "Warning: Deprecated, and replaced by enableArtifact. Claude Code still honors disableArtifact: true as equivalent to enableArtifact: false, and ignores disableArtifact: false. Default: unset, so the tool follows your account's availability." },
    CcKey { key: "disableDeepLinkRegistration", tab: 11, kind: Choice(&["disable"]), scope: "Any file", tui: false, help: "Stop Claude Code from registering the claude-cli:// protocol handler with the operating system. Deep links let external tools open a Claude Code session with a pre-filled prompt. Set this in environments where protocol handler registration is restricted or managed separately. Default: unset, so Claude Code registers the handler." },
    CcKey { key: "disableRemoteControl", tab: 11, kind: Bool, scope: "Any file", tui: false, help: "Turn off Remote Control: Claude Code then refuses claude remote-control, the --remote-control flag, auto-start, and the in-session toggle, and reports that your organization's policy disabled it. Place it in managed settings for per-device MDM enforcement. Default: false." },
    CcKey { key: "enableArtifact", tab: 11, kind: Bool, scope: "Any file", tui: false, help: "Turn off the Artifact tool, which publishes session output as a private web page on claude.ai. When you turn the Artifacts row off in /config, Claude Code writes this key to your user settings, so you don't usually edit it by hand. Default: unset, so the tool follows your account's availability." },
    CcKey { key: "inputNeededNotifEnabled", tab: 11, kind: Bool, scope: "Any file", tui: false, help: "Get a push notification on your phone when a permission prompt or question is waiting for your input. Claude Code sends these only while Remote Control is connected. Appears in /config as Push when actions required. Default: false." },
    CcKey { key: "preferredNotifChannel", tab: 11, kind: Choice(&["auto", "terminal_bell", "iterm2", "iterm2_with_bell", "kitty", "ghostty", "notifications_disabled"]), scope: "Any file", tui: false, help: "Choose how Claude Code notifies you when a task completes or a permission prompt is waiting. A mod's notifications use the same setting. Appears in /config as Local notifications. Default: \"auto\"." },
    CcKey { key: "remote.defaultEnvironmentId", tab: 11, kind: Text, scope: "Any file", tui: false, help: "Pick the default cloud environment for cloud sessions you create from the CLI, such as with claude --cloud. Claude Code writes this key to your user settings when you pick an environment with /remote-env. Default: unset, so Claude Code uses the Anthropic-hosted environment when your list has one, and otherwise the first environment in your list that isn't a Remote Control bridge environment, or the first environment when every one is a bridge environment." },
    CcKey { key: "remoteControlAtStartup", tab: 11, kind: Bool, scope: "Any file", tui: false, help: "Connect Remote Control automatically when each interactive session starts, instead of waiting for /remote-control. Set it to true to turn auto-connect on, false to turn it off. Appears in /config as Enable Remote Control for all sessions. Default: unset, so the auto-connect default applies." },
    CcKey { key: "sshConfigs", tab: 11, kind: Json, scope: "User or managed", tui: false, help: "Add SSH connections to the Desktop environment selector. Administrators use sshConfigs to distribute shared connections to a team. Users can select a managed connection and set their own Worktree folder for it. They can't edit its other fields or delete it in the app. Default: unset." },
    CcKey { key: "sshHostCommands", tab: 11, kind: Json, scope: "User or managed", tui: false, help: "Add SSH connections whose host comes from a command to the Desktop environment selector. When you create a connection or replace its host, Desktop runs the entry's command on your computer and connects to the host that the command prints. Requires Claude Desktop v3.6556.0 or later on macOS or Linux, signed in with a Claude account. Default: unset." },
    CcKey { key: "apiKeyHelper", tab: 12, kind: Text, scope: "Any file", tui: false, help: "Run your own command to produce the credential Claude Code sends with model requests. Claude Code runs the command through the system shell, /bin/sh on macOS and Linux and cmd on Windows, and sends its output as both the X-Api-Key and Authorization: Bearer headers. Use it for dynamic or rotating credentials, such as short-lived tokens fetched from a vault. Default: unset, so Claude Code doesn't run a helper." },
    CcKey { key: "awsAuthRefresh", tab: 12, kind: Text, scope: "Any file", tui: false, help: "Run your own command, such as aws sso login, to refresh the credentials in your .aws directory when the ones Claude Code has for Amazon Bedrock stop working. Claude Code checks the current credentials against STS first and runs the command only when that check fails, then reads the refreshed .aws directory. Default: unset, so Claude Code doesn't refresh AWS credentials for you." },
    CcKey { key: "awsCredentialExport", tab: 12, kind: Text, scope: "Any file", tui: false, help: "Run your own command that prints AWS credentials as JSON, so Claude Code can call Amazon Bedrock with credentials that don't live in your .aws directory. Claude Code accepts the aws sts output shape and the flat aws configure export-credentials shape, and scopes the credentials to its own Bedrock client, so the shell commands Claude runs still see your ambient credentials. Default: unset, so Claude Code uses the ambient AWS credential chain." },
    CcKey { key: "forceLoginMethod", tab: 12, kind: Choice(&["claudeai", "console", "gateway"]), scope: "Any file", tui: false, help: "Restrict which kind of account people can log in with. Set \"claudeai\" to allow only claude.ai accounts, \"console\" to allow only Claude Console accounts, or \"gateway\" to send people to a cloud gateway instead of a first-party login. Administrators set it in managed settings and pair it with forceLoginOrgUUID to keep developers' claude.ai logins inside one organization. Default: unset, so people pick a login method." },
    CcKey { key: "forceLoginGatewayUrl", tab: 12, kind: Text, scope: "User or managed", tui: false, help: "Set the gateway URL the /login Cloud gateway screen connects to, so people reach your cloud gateway without typing its address. The screen has no URL field: with this key set, it shows your gateway URL and connects when the person presses Enter; without it, it tells them to contact their IT administrator. Default: unset, so the Cloud gateway screen shows an error telling people to contact their IT administrator." },
    CcKey { key: "forceLoginOrgUUID", tab: 12, kind: Text, scope: "Any file", tui: false, help: "From a managed source, require claude.ai account logins to belong to one Anthropic organization, given as a single UUID, or to any of several organizations, given as an array. From any settings file, Claude Code also uses a single UUID to pre-select that organization during a claude.ai or Claude Console login, and pre-selects nothing for an array. If you set the key in any settings file, Claude Code also stops offering the keyless Console sign-in in the sessions that file applies to and creates an API key instead. Default: unset, so any organization can log in." },
    CcKey { key: "gcpAuthRefresh", tab: 12, kind: Text, scope: "Any file", tui: false, help: "Run your own command to refresh Google Cloud Application Default Credentials when Claude Code finds they've expired or can't be loaded, so Google Cloud's Agent Platform requests keep working without you re-authenticating by hand. Default: unset, so Claude Code's credential error tells you to run gcloud auth application-default login yourself." },
    CcKey { key: "otelHeadersHelper", tab: 12, kind: Text, scope: "Any file", tui: false, help: "Run your own command to generate the headers Claude Code sends with OpenTelemetry exports, for backends whose tokens rotate. Claude Code runs it at startup and periodically after that, and expects a JSON object of string header values on stdout. Default: unset, so Claude Code adds no helper-generated headers." },
    CcKey { key: "autoUpdatesChannel", tab: 13, kind: Choice(&["latest", "stable"]), scope: "Any file", tui: false, help: "Choose which release channel background auto-updates and claude update follow. Set \"stable\" for a version that is typically about one week old and skips releases with major regressions, or \"latest\" for the most recent release. Default: unset, so Claude Code follows \"latest\"." },
    CcKey { key: "minimumVersion", tab: 13, kind: Text, scope: "Any file", tui: false, help: "Keep background auto-updates and claude update from installing any version below this one, so moving to the \"stable\" channel doesn't downgrade you from a newer \"latest\" build. Claude Code writes this key for you when you choose to stay on your current version while switching channels in /config, and clears it when you switch back to \"latest\". Default: unset, so updates can install any version the channel offers." },
    CcKey { key: "cleanupPeriodDays", tab: 14, kind: Number, scope: "Any file", tui: false, help: "Set how many days Claude Code keeps session transcripts and other application data before deleting them. Claude Code runs the deletion as a background sweep after a session starts, as long as it can safely determine the retention period. The sweep deletes transcripts without showing a message, so a session you haven't used for longer than the retention period no longer appears in the /resume picker. Default: 30." },
    CcKey { key: "desktopSessionCleanupPeriodDays", tab: 14, kind: Number, scope: "User or managed", tui: false, help: "Set an age limit in days for the transcripts of sessions you started or most recently continued in Claude Desktop or Cowork. Without this key, Claude Code keeps those transcripts at any age. Claude Code deletes each one once it's older than both this limit and cleanupPeriodDays, so with cleanupPeriodDays at its default of 30, a value of 7 still keeps them 30 days. Cleaned up automatically lists the cases where cleanupPeriodDays applies instead and Claude Code ignores this key. Requires Claude Code v2.1.248 or later. Default: 0, which sets no age limit." },
    CcKey { key: "feedbackDrafts", tab: 14, kind: Choice(&["notify", "quiet", "off"]), scope: "User or managed", tui: false, help: "Control Claude-drafted feedback: whether Claude can queue feedback drafts for you to review, and whether Claude Code shows a card when Claude queues one. Default: \"notify\"." },
    CcKey { key: "feedbackSurveyRate", tab: 14, kind: Number, scope: "Any file", tui: false, help: "Set the probability that the session quality survey appears when a session is eligible for it. Set 0 to keep the survey from appearing. Default: unset, so Claude Code uses the rate Anthropic sets remotely, or its built-in rate of 0.005 on Amazon Bedrock, Google Cloud's Agent Platform, and Microsoft Foundry, which don't receive remote configuration." },
    CcKey { key: "skipWebFetchPreflight", tab: 14, kind: Bool, scope: "Any file", tui: false, help: "Skip the WebFetch domain safety check, which sends each requested hostname to api.anthropic.com before fetching. Set true in environments that block traffic to Anthropic, such as Amazon Bedrock, Google Cloud's Agent Platform, or Microsoft Foundry deployments with restrictive egress. Default: unset, so the check runs before the first fetch to each hostname in a session." },
];
